"""Reliability helpers around an LLM callable: llm(prompt: str) -> str."""
import json
import re


class LLMOutputError(Exception):
    """The model never produced acceptable output."""


_PLACEHOLDER = re.compile(r"\{\{\s*(\w+)\s*\}\}")


def render_prompt(template, variables):
    def sub(match):
        name = match.group(1)
        if name not in variables:
            raise KeyError(name)
        return str(variables[name])

    return _PLACEHOLDER.sub(sub, template)


_FENCE = re.compile(r"```(?:json|JSON)?\s*(.*?)```", re.S)


def extract_json(text):
    candidates = [text.strip()]
    candidates += [m.group(1).strip() for m in _FENCE.finditer(text)]
    for cand in candidates:
        try:
            return json.loads(cand)
        except ValueError:
            pass
    decoder = json.JSONDecoder()
    for i, ch in enumerate(text):
        if ch in "{[":
            try:
                obj, _ = decoder.raw_decode(text[i:])
                return obj
            except ValueError:
                continue
    raise ValueError("no valid JSON found in model output")


def call_with_retries(llm, prompt, validate=None, max_retries=2):
    if max_retries < 0:
        raise ValueError("max_retries must be >= 0")
    attempts = max_retries + 1
    current = prompt
    last_error = "unknown"
    for _ in range(attempts):
        text = llm(current)
        try:
            obj = extract_json(text)
            if validate is not None and not validate(obj):
                raise ValueError("validation failed")
            return obj
        except ValueError as exc:
            last_error = str(exc)
            current = prompt + f"\n\nYour previous answer was invalid: {last_error}. Return only valid JSON."
    raise LLMOutputError(f"no valid output after {attempts} attempts: {last_error}")

