import pytest
from llm_utils import render_prompt, extract_json, call_with_retries, LLMOutputError


class FakeLLM:
    def __init__(self, *replies):
        self.replies = list(replies)
        self.prompts = []

    def __call__(self, prompt):
        self.prompts.append(prompt)
        return self.replies.pop(0)


def test_r1_render_prompt_fills_placeholders():
    assert render_prompt("Hello {{name}}, you are {{ age }}.", {"name": "Ada", "age": 36}) == "Hello Ada, you are 36."


def test_r2_extract_json_from_a_code_fence():
    assert extract_json('Sure!\n```json\n{"a": 1}\n```') == {"a": 1}


def test_r3_retry_prompt_contains_the_reason():
    llm = FakeLLM("not json", '{"ok": true}')
    assert call_with_retries(llm, "Give JSON") == {"ok": True}
    assert len(llm.prompts) == 2
    assert llm.prompts[1].startswith("Give JSON")
    assert "Your previous answer was invalid" in llm.prompts[1]


def test_r4_gives_up_with_llm_output_error():
    llm = FakeLLM("x", "y", "z")
    with pytest.raises(LLMOutputError):
        call_with_retries(llm, "p", max_retries=2)
    assert len(llm.prompts) == 3


def test_r5_validate_callback_rejects_bad_objects():
    llm = FakeLLM('{"n": 1}', '{"n": 2}')
    assert call_with_retries(llm, "p", validate=lambda o: o["n"] == 2) == {"n": 2}

