import pytest
from llm_utils import render_prompt, extract_json, call_with_retries, LLMOutputError


class FakeLLM:
    def __init__(self, *replies):
        self.replies = list(replies)
        self.prompts = []

    def __call__(self, prompt):
        self.prompts.append(prompt)
        return self.replies.pop(0)


def test_r1_missing_variable_raises_key_error_with_the_name():
    with pytest.raises(KeyError) as e:
        render_prompt("Hi {{who}}", {"other": 1})
    assert e.value.args[0] == "who"


def test_r1_extra_variables_and_repeated_placeholders():
    assert render_prompt("{{a}}-{{a}}-{{ b }}", {"a": 1, "b": "x", "unused": 9}) == "1-1-x"
    assert render_prompt("no placeholders", {}) == "no placeholders"


def test_r2_pure_json_arrays_and_objects():
    assert extract_json(" [1, 2, 3] ") == [1, 2, 3]
    assert extract_json('{"a": {"b": [1]}}') == {"a": {"b": [1]}}


def test_r2_plain_fence_and_surrounding_prose():
    assert extract_json('```\n{"k": "v"}\n```') == {"k": "v"}
    assert extract_json('Here is the result: {"score": 7} - hope that helps!') == {"score": 7}
    assert extract_json('Options: [1, 2] and that is all') == [1, 2]


def test_r2_skips_broken_fragments_before_the_real_json():
    assert extract_json('a {broken then {"ok": 1}') == {"ok": 1}


def test_r2_raises_value_error_when_there_is_no_json():
    for bad in ["", "just words", "{unclosed", "```\nnot json\n```"]:
        with pytest.raises(ValueError):
            extract_json(bad)


def test_r3_first_valid_answer_is_returned_without_extra_calls():
    llm = FakeLLM('{"a": 1}', '{"a": 2}')
    assert call_with_retries(llm, "p") == {"a": 1}
    assert len(llm.prompts) == 1


def test_r3_feedback_is_built_from_the_original_prompt_each_time():
    llm = FakeLLM("bad", "worse", '{"ok": 1}')
    call_with_retries(llm, "ORIGINAL", max_retries=2)
    assert llm.prompts[0] == "ORIGINAL"
    assert llm.prompts[1].startswith("ORIGINAL\n\nYour previous answer was invalid")
    assert llm.prompts[2].startswith("ORIGINAL\n\nYour previous answer was invalid")
    assert llm.prompts[2].count("Your previous answer was invalid") == 1


def test_r4_zero_retries_means_exactly_one_call():
    llm = FakeLLM("nope")
    with pytest.raises(LLMOutputError):
        call_with_retries(llm, "p", max_retries=0)
    assert len(llm.prompts) == 1


def test_r4_negative_retries_is_a_value_error():
    with pytest.raises(ValueError):
        call_with_retries(FakeLLM("x"), "p", max_retries=-1)


def test_r4_exceptions_from_the_llm_propagate():
    def boom(prompt):
        raise RuntimeError("network down")

    with pytest.raises(RuntimeError):
        call_with_retries(boom, "p")


def test_r5_falsy_validation_counts_as_a_failure_and_is_reported():
    llm = FakeLLM('{"n": 1}', '{"n": 1}', '{"n": 1}')
    with pytest.raises(LLMOutputError) as e:
        call_with_retries(llm, "p", validate=lambda o: False, max_retries=2)
    assert "validation failed" in str(e.value)
    assert len(llm.prompts) == 3
